const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('.site-header nav');toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('project-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget);const brief=`THEANTCOMPANY — PROJECT BRIEF\n\nName: ${data.get('name')}\nCompany: ${data.get('company')||'Not specified'}\nService: ${data.get('service')}\n\nProject details:\n${data.get('details')}`;const note=document.getElementById('form-note');try{await navigator.clipboard.writeText(brief);note.textContent='Project brief copied. Paste it into your preferred email or messaging app to send it to TheANTCompany.'}catch{note.textContent='Your brief is ready. Select the details above and copy them into your preferred email or messaging app.'}});
